sys_script_client.script:
function onChange(control, oldValue, newValue, isLoading, isTemplate) {
    if (isLoading || newValue === '') {
        return;
    }

    // Safely get the selected segment and force lowercase for JSON matching
    var rawSegment = g_form.getValue('segment');
    if (!rawSegment) {
        g_form.addErrorMessage('Please select a Segment before choosing a Role.');
        return;
    }
    var segment = rawSegment.toString().toLowerCase();

    // Master mapping. The keys below MUST match the 'Value' column of your Choice List.
    var matrixMap = {
        'cement': {
            'NT Cement RHM':              { min: 0, max: 2500000, nod: 30, pan_india: 'false', seq: 10 },
            'NT Cement ZHM':              { min: 2500001, max: 7500000, nod: 45, pan_india: 'false', seq: 20 },
            'NT Cement ZCH - Commercial': { min: 5000001, max: 999999999, nod: 0, pan_india: 'false', seq: 25 },
            'NT Cement NSH':              { min: 7500001, max: 15000000, nod: 60, pan_india: 'true', seq: 30 },
            'HO - Commercial':            { min: 15000001, max: 999999999, nod: 0, pan_india: 'true', seq: 40 },
            'CCH - PAN':                  { min: 15000001, max: 20000000, nod: 0, pan_india: 'true', seq: 50 },
            'CMO_BH - PAN':               { min: 20000001, max: 30000000, nod: 0, pan_india: 'true', seq: 60 },
            'CFO - PAN':                  { min: 30000001, max: 50000000, nod: 0, pan_india: 'true', seq: 70 },
            'MD - PAN':                   { min: 50000001, max: 999999999, nod: 0, pan_india: 'true', seq: 80 }
        },
        'rmc': {
            'NT RMC TSM':                 { min: 0, max: 400000, nod: 0, pan_india: 'false', seq: 10 },
            'NT RMC RH_CH':               { min: 400001, max: 1100000, nod: 0, pan_india: 'false', seq: 20 },
            'NT RMC ZCH - Commercial':    { min: 2500000, max: 999999999, nod: 0, pan_india: 'false', seq: 25 },
            'NT RMC ZH':                  { min: 1100001, max: 3200000, nod: 0, pan_india: 'false', seq: 30 },
            'NT RMC Head_RMC':            { min: 3200001, max: 5300000, nod: 0, pan_india: 'true', seq: 40 },
            'NT RMC Head_Key_RMC':        { min: 5300001, max: 7500000, nod: 0, pan_india: 'true', seq: 50 },
            'HO - Commercial':            { min: 7500001, max: 999999999, nod: 0, pan_india: 'true', seq: 55 },
            'CCH - PAN':                  { min: 7500001, max: 15000000, nod: 0, pan_india: 'true', seq: 60 },
            'CMO_BH - PAN':               { min: 15000001, max: 25000000, nod: 0, pan_india: 'true', seq: 70 },
            'CFO - PAN':                  { min: 25000001, max: 50000000, nod: 0, pan_india: 'true', seq: 80 },
            'MD - PAN':                   { min: 50000001, max: 999999999, nod: 0, pan_india: 'true', seq: 90 }
        },
        'bpd': {
            'NT BPD TSH':                 { min: 0, max: 250000, nod: 0, pan_india: 'false', seq: 10 },
            'NT BPD ZH_BPD':              { min: 250001, max: 1200000, nod: 0, pan_india: 'false', seq: 20 },
            'NT BPD HS_BPD':              { min: 1200001, max: 2000000, nod: 0, pan_india: 'true', seq: 30 },
            'NT BPD ZCH - Commercial':    { min: 2500000, max: 999999999, nod: 0, pan_india: 'false', seq: 35 },
            'NT BPD H_BPD':               { min: 2000001, max: 5000000, nod: 0, pan_india: 'true', seq: 40 },
            'HO - Commercial':            { min: 5000001, max: 999999999, nod: 0, pan_india: 'true', seq: 45 },
            'CCH - PAN':                  { min: 5000001, max: 10000000, nod: 0, pan_india: 'true', seq: 50 },
            'CMO_BH - PAN':               { min: 10000001, max: 25000000, nod: 0, pan_india: 'true', seq: 60 },
            'CFO - PAN':                  { min: 25000001, max: 50000000, nod: 0, pan_india: 'true', seq: 70 },
            'MD - PAN':                   { min: 50000001, max: 999999999, nod: 0, pan_india: 'true', seq: 80 }
        }
    };

    var roleData = matrixMap[segment] ? matrixMap[segment][newValue] : null;

    if (roleData) {
        g_form.setValue('min_amount', roleData.min);
        g_form.setValue('max_amount', roleData.max);
        g_form.setValue('sequence_order', roleData.seq);
        g_form.setValue('pan_india', roleData.pan_india);

        if (roleData.nod > 0) {
            g_form.setValue('number_of_days', roleData.nod);
        } else {
            g_form.clearValue('number_of_days'); 
        }
    } else {
        // Failsafe: clears fields if an unrecognized choice is selected
        g_form.clearValue('min_amount');
        g_form.clearValue('max_amount');
        g_form.clearValue('sequence_order');
        g_form.clearValue('pan_india');
        g_form.clearValue('number_of_days');
    }
}
